  --glory-blue: #0a3161;
  --glory-secondary-blue: #154fd7;
  --error-red: #db095b;
  --brand-green: #a4ce4e;
  --brand-dark-green: #297d72;
  --brand-purple: #0061a0;
  --brand-red: #e80939;
  --brand-yellow: #ffbd01;
  --brand-orange: #ffb500;
  --primary-blue: #007abc;
  --secondary-blue: #0090da;
  --light-blue: #8ec5ec;
  --cal-shadow: rgba(60, 64, 67, 0.3) 0px 1px 2px 0px,
    rgba(60, 64, 67, 0.15) 0px 1px 3px 1px;
  --btn-shadow: rgba(60, 64, 67, 0.2) 0px 1px 2px 0px,
    rgba(60, 64, 67, 0.2) 0px 1px 3px 1px;
}

.Toastify__toast-theme--light {
  background: var(--secondary-blue);
}

.Toastify__close-button--light {
  color: white;
}

.Toastify__toast--error {
  background: var(--error-red) !important;
}

.Toastify__toast--success {
  background: var(--brand-dark-green) !important;
}

.Toastify__toast {
  --toastify-color-progress-light: white;
  --toastify-color-progress-error: white;
  --toastify-color-progress-success: white;
