html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
}

html {
  /* this makes sure the padding and the border is included in the box sizing */
  box-sizing: border-box;
  overflow-y: none;
  overflow-x: none;
}

*,
*::before,
*::after {
  position: relative;
  box-sizing: inherit;
}

body {
  font-family: 'Lato', sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: #333;
}

#root {
  display: flex;
  position: relative;
  width: 100vw;
  height: 100vh;
}

button {
  transition: background-color 200ms ease-in-out;
}

.banner-vote-wrapper {
  display: flex;
  justify-content: center;
  width: 100%;
  background: #212693;
}

.banner-vote {
  text-decoration: none;
  width: fit-content;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 17px;
  color: #fff;
  line-height: 125%;
  padding: 15px 12px 10px;
  font-weight: 500;
  text-transform: uppercase;
  text-align: center;
  display: block;
  letter-spacing: 1px;
  cursor: pointer;
  font-family: 'Balto', sans-serif;
}

.banner-vote > span:hover {
  border-bottom: 2px solid white;
}

.election-year {
  margin: 0;
  font-family: 'Saira Condensed', sans-serif;
  font-weight: 200;
  font-size: 5rem;
  line-height: 5rem;
}

.election-year > span {
  display: inline-block;
  z-index: 1;
  margin-left: 15%;
  transform: scale(0.8, 1);
  background: linear-gradient(
    0deg,
    rgba(51, 51, 51, 1) 0%,
    rgba(51, 51, 51, 1) 50%,
    rgba(255, 255, 255, 1) 50%
  );
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.election-year::before {
  position: absolute;
  width: 110%;
  height: 75%;
  top: -25%;
  /* left: -25%; */
  background: var(--glory-blue);
  content: '';
  z-index: 0;
}

.border-solid {
  border-width: 0px;
}

footer {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  width: 100%;
  background: transparent;
  font-family: 'Lato', sans-serif;
  color: white;
  text-align: center;
}

@media only screen and (min-width: 1200px) {
  footer {
    width: 40%;
    align-items: start !important;
    padding: 0rem 1rem;
  }

  .copy-right {
    line-height: 150%;
    font-size: 0.5rem !important;
  }
}

footer > p {
  margin: 0;
}

footer > * a {
  cursor: pointer;
  color: white;
  text-decoration: none !important;
}

footer > * a:hover {
  color: white !important;
  text-decoration: underline !important;
}

.copy-right > :first-child {
  letter-spacing: 1px;
}

.copy-right {
  line-height: 150%;
  font-size: 0.8rem;
}

.made-in {
  text-align: center;
  margin: 0;
}

.made-in > span {
  font-weight: 500;
  border: 2px solid white;
  padding: 0.5rem;
  border-radius: 0.5rem;
}

.american-flag-bh {
  background-position: center center;
  background-image: url('https://shop.gop.com/cdn/shop/files/Flag_Banner_-_Generic.png?v=1661790299');
}

form {
  width: max-content;
}

.pg-cn {
  /* make space for actions banner */
  --actions-banner-mt: 54px;
  overflow: hidden;
  min-width: fit-content;
  background: var(--glory-red-web);
  padding-bottom: 1rem;
}

code {
  font-family: source-code-pro, Menlo, Monaco, Consolas, 'Courier New',
    monospace;
}

.cs-loader-left::after {
  content: '';
  position: absolute;
  height: 10px;
  width: 10px;
  border-radius: 100%;
  border: 4px solid rgba(0, 0, 0, 0.1);
  border-top-color: var(--secondary-blue);
  top: calc(50% - 9px);
  left: calc(100% + 15px);
  animation: cs-loader-spin 1s linear infinite;
}

.cs-loader-center::before {
  content: 'Processing payment...';
  position: absolute;
  display: flex;
  padding-top: 50%;
  justify-content: center;
  color: var(--brand-dark-green);
  font-weight: 600;
  text-align: center;
  height: 100%;
  width: 100%;
  top: 0;
  left: 0;
  font-size: 1.5rem;
  background-color: rgba(255, 255, 255, 0.3);
  -webkit-backdrop-filter: blur(5px);
          backdrop-filter: blur(5px);
  pointer-events: none;
  z-index: 90;
}

.cs-loader-center::after {
  content: '';
  position: absolute;
  height: 25px;
  width: 25px;
  border-radius: 100%;
  border: 4px solid rgba(255, 255, 255, 0.471);
  border-top-color: var(--secondary-blue);
  top: calc(50% - 12.5px);
  left: calc(50% - 12.5px);
  animation: cs-loader-spin 1s linear infinite;
  z-index: 99;
}

.text-shadow-sm {
  text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.4);
}

@keyframes cs-loader-spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes bounceHorizontal {
  0% {
    transform: translateX(0px);
  }

  70% {
    transform: translateX(-2.5px);
  }

  100% {
    transform: translateX(0px);
  }
}

.header-md {
  font-size: 1.75rem;
